"""Build the two independent cabinet alternatives; source documents are data."""
from pathlib import Path
import re,json
ROOT=Path(__file__).resolve().parents[1]
version=(ROOT/'VERSION').read_text(encoding='utf-8').strip()
overview=(ROOT/'sources/cabinet-overview-original-2026-11-05.html').read_text(encoding='utf-8')
assert not re.search(r'<script\b[^>]+src=|fetch\(|XMLHttpRequest|<iframe|<form',overview,re.I)
policy='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; img-src data:; base-uri \'none\'; form-action \'none\'">'
style='''<style>html,body{height:100%;overflow:hidden}body{display:flex;flex-direction:column;--ink:#20242c;--line:#d8dde5;--paper:#fff;--green:#2563eb}.overview-banner{flex:none;height:34px;padding:9px 16px;font:12px Arial;background:#f4f6f8;border-bottom:1px solid var(--line)}.side{top:34px;width:220px;background:#fff;color:var(--ink);border-right:1px solid var(--line);padding:20px 12px}.logo{letter-spacing:0;font-size:22px;padding:0 10px 22px}.nav button{color:#475569;border-radius:4px}.nav button.active,.nav button:hover{color:#1d4ed8;background:#edf4ff}.user{border-color:var(--line)}.user small{color:#647084}.main{margin-left:220px;min-height:0;flex:1;display:flex;flex-direction:column;overflow:hidden}.top{flex:none;height:56px;position:static;padding:0 24px}.content{width:100%;margin:0 auto;flex:1;min-height:0;overflow:auto;padding:24px}.title h1{font-size:26px}.balance{background:#f8fafc;color:var(--ink);border:1px solid var(--line);border-radius:6px;gap:22px}.balance small,.balance span{color:#647084}.balance strong{font-size:28px}.reserved{border-color:var(--line)}.primary{background:#2563eb;color:#fff}.secondary{background:#fff;color:#20242c;border:1px solid var(--line)}.card,.panel,.stat,.quick button,.table,.empty,.modal,.context,.primary,.secondary{border-radius:5px;box-shadow:none}.card:after{display:none}.icon{display:none}.card h3{margin-top:4px}.modal-bg{overflow:auto}.modal{max-height:calc(100dvh - 40px);overflow:auto}.row{min-width:0}.row>*{min-width:0;overflow-wrap:anywhere}@media(max-width:850px){.side{width:75px}.main{margin-left:75px}.content{padding:20px}.logo{font-size:16px;padding-left:0}}@media(max-width:560px){.side{position:static;display:block;width:100%;padding:5px;border-bottom:1px solid var(--line)}.side .logo,.side .user{display:none}.nav{display:flex;overflow:auto;gap:4px}.nav button{font-size:11px;white-space:nowrap;padding:10px 8px}.nav button:before{display:none}.main{margin-left:0}.content{padding:18px 12px}.overview-banner{height:auto;min-height:34px}.title h1{font-size:24px}.balance{padding:20px}.reserved{border-top-color:var(--line)}}</style>'''
overview=overview.replace('</head>',policy+style+'</head>',1).replace('<body>','<body><div class="overview-banner">ЛК · сводная информация · демонстрационные данные · v'+version+'</div>',1)
overview=overview.replace('Операцию юридически выполняет платформа ВЕРО через номинальный счёт.','Демонстрация интерфейса. Деньги не переводятся.').replace('scrollTo(0,0)','document.querySelector(".content").scrollTop=0')
overview=re.sub(r'<title>[^<]*</title>','<title>ВЕРО — вариант ЛК со сводкой</title>',overview,count=1)
catalog=json.loads((ROOT/'src/brief-catalog.json').read_text(encoding='utf-8'))
script=(ROOT/'src/cabinet-brief.js').read_text(encoding='utf-8').replace('__BRIEF_CATALOG__',json.dumps(catalog,ensure_ascii=False))
history=(ROOT/'src/prototype-history.js').read_text(encoding='utf-8')+'\n'+(ROOT/'src/history-brief-adapter.js').read_text(encoding='utf-8')
script=script.replace('reset();\n})();','reset();\n'+history+'\n})();',1)
brief=(ROOT/'src/cabinet-brief.html').read_text(encoding='utf-8').replace('__VERSION__',version).replace('__BRIEF_CSS__',(ROOT/'src/cabinet-brief.css').read_text(encoding='utf-8')).replace('__BRIEF_JS__',script)
for name,content in [('cabinet-overview.html',overview),('cabinet-brief.html',brief)]:
 for folder in [ROOT,ROOT/'web',ROOT/'deliverables']:
  folder.mkdir(exist_ok=True);(folder/name).write_text(content,encoding='utf-8')
print('Built independent summary cabinet and UX-brief cabinet; source files remain unchanged.')
